public partial class MainWindow:Window {
 readonly LauncherSettings settings=LauncherSettings.Load();List<VersionEntry> versions=new();string page="Home",filesFolder="";bool initialized,launching;int generation;Process? game;SkinSession? skinSession;
 readonly ConcurrentQueue<string> queue=new();readonly DispatcherTimer logTimer=new(){Interval=TimeSpan.FromMilliseconds(200)};StreamWriter? logfile;
 public TaskCompletionSource Ready{get;}=new(TaskCreationOptions.RunContinuationsAsynchronously);
 public MainWindow(bool preview=false){suppressProfileSave=preview;Loc.Language=settings.Language;Loc.ApplyResources();InitializeComponent();InitializeUpgrade(preview);NicknameBox.Text=settings.Nickname;lastSavedNickname=settings.Nickname;RootBox.Text=settings.GameRoot;JavaBox.Text=settings.JavaPath;RamSlider.Value=Math.Clamp(settings.MemoryMb,1024,16384);IsolatedBox.IsChecked=settings.Isolated;MotionBox.IsChecked=settings.ReduceMotion;ApplyMotionPreference();skinModel=settings.SkinModel;
  logTimer.Tick+=(s,e)=>FlushLog();logTimer.Start();Loaded+=async(s,e)=>{initialized=true;Navigate("Home");try{await RefreshVersions();}finally{Ready.TrySetResult();}};
  Closing+=(s,e)=>{nicknameSaveTimer.Stop();PersistNickname();installCts?.Cancel();modsSearchCts?.Cancel();modInstallCts?.Cancel();modsDebounce.Stop();catalogCts.Cancel();SaveWindowBounds();FlushLog();logfile?.Dispose();logfile=null;logTimer.Stop();};
 }
 void Log(string text){text=Regex.Replace(text,@"(?i)(access[_-]?token|refresh[_-]?token|password|authorization)([\s=:]+)[^\s,;]+","$1$2[hidden]");queue.Enqueue(DateTime.Now.ToString("HH:mm:ss")+"  "+text);}
 void FlushLog(){if(queue.IsEmpty)return;var lines=new List<string>();while(lines.Count<200&&queue.TryDequeue(out var line))lines.Add(line);foreach(var l in lines)logfile?.WriteLine(l);logfile?.Flush();LogBox.AppendText(string.Join(Environment.NewLine,lines)+Environment.NewLine);if(LogBox.LineCount>1800)LogBox.Text=string.Join(Environment.NewLine,LogBox.Text.Split('\n').TakeLast(1400));if(settings.ScrollLog)LogBox.ScrollToEnd();}
 void Status(string text,bool error=false){StatusText.Text=Loc.T(text);StatusText.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(error?"#F4AB87":"#8EA893"));}
 void Navigate(string name){page=name;ModsPage.Visibility=name=="Mods"?Visibility.Visible:Visibility.Collapsed;SkinsPage.Visibility=name=="Skins"?Visibility.Visible:Visibility.Collapsed;if(name=="Skins")RefreshSkin();HomePage.Visibility=name=="Home"?Visibility.Visible:Visibility.Collapsed;LibraryPage.Visibility=name=="Library"?Visibility.Visible:Visibility.Collapsed;SettingsPage.Visibility=name=="Settings"?Visibility.Visible:Visibility.Collapsed;LogsPage.Visibility=name=="Logs"?Visibility.Visible:Visibility.Collapsed;FilesPage.Visibility=name=="Worlds"?Visibility.Visible:Visibility.Collapsed;
  string title=name switch{"Skins"=>Loc.T("Скины"),"Library"=>Loc.T("Библиотека"),"Mods"=>Loc.T("Моды, ресурспаки и шейдеры"),"Worlds"=>Loc.T("Твои миры"),"Settings"=>Loc.T("Настройки"),"Logs"=>Loc.T("Журнал запуска"),_=>Loc.T("Главная")};PageTitle.Text=title;
  PageSubtitle.Text=name switch{"Skins"=>Loc.T("Твой образ в Minecraft"),"Library"=>Loc.T($"{versions.Count} установленных версий · выбери свою"),"Mods"=>Loc.T("Modrinth · найди своё следующее приключение"),"Worlds"=>Loc.T("Истории, которые ты создал"),"Settings"=>Loc.T("Настрой пространство под себя"),"Logs"=>Loc.T("Проверка файлов и вывод игры"),_=>Loc.T("Всё готово для нового приключения")};
  foreach(var b in new[]{HomeNav,LibraryNav,SkinsNav,ModsNav,WorldsNav,SettingsNav,LogsNav})AnimateNavigation(b,(string)b.Tag==name);
  if(name=="Mods")_ = OpenModsAsync();if(name=="Worlds")ShowFiles();AnimatePage(name);
 }
 async Task RefreshVersions(){int stamp=++generation;Status(Loc.T("Поиск версий…"));try{var found=await Task.Run(()=>Versions.Scan(settings.GameRoot,Log));if(stamp!=generation)return;versions=found.Concat(Modpacks.Scan()).ToList();InstalledCountLabel.Text=Loc.T($"{versions.Count} установленных версий");MemorySummaryLabel.Text=Loc.T($"{settings.MemoryMb/1024d:0.#} ГБ · ")+(settings.Isolated?Loc.T("отдельные сборки"):Loc.T("общая папка"));HomeVersions.ItemsSource=versions.Take(3);HomeEmpty.Visibility=versions.Count==0?Visibility.Visible:Visibility.Collapsed;AllVersions.ItemsSource=versions;UpdateChoices(settings.Version);Status(versions.Count==0?Loc.T("Выбери папку Minecraft в настройках"):Loc.T($"Найдено версий: {versions.Count}. Выбери версию и нажми «Играть»."));Log(Loc.T($"Сканирование: {versions.Count} версий. Корень: {settings.GameRoot}"));if(page=="Library")Navigate(page);}catch(Exception e){Status(e.Message,true);Log(e.Message);}}
 public async Task PreviewPageAsync(string name,string? previewRoot=null){if(name=="UpgradeChecks"&&previewRoot!=null){await CheckUpgradeUiAsync(previewRoot);return;}if(name=="PublicHome"){Loc.Language="en";Loc.ApplyResources();NicknameBox.Text="Player";selectedChoice=choices.FirstOrDefault(v=>v.Id=="1.21.1");UpdateChoices(selectedChoice?.Id);Navigate("Home");return;}if(name=="EnglishHome"){Loc.Language="en";Loc.ApplyResources();Navigate("Home");return;}if(name=="RussianSettings"){Loc.Language="ru";Loc.ApplyResources();Navigate("Settings");return;}if(name=="EnglishSettings"){Loc.Language="en";Loc.ApplyResources();Navigate("Settings");return;}if(name=="ModpacksPreview"){catalogType="modpack";Navigate("Mods");await modsLoadTask;return;}if(name=="ShaderChecks"&&previewRoot!=null){await CheckShadersAsync(previewRoot);return;}if(name=="ShadersPreview"){catalogType="shader";Navigate("Mods");await modsLoadTask;return;}if(name=="ProfilePackChecks"&&previewRoot!=null){await CheckProfilePacksAsync(previewRoot);return;}if(name=="PacksPreview"){catalogType="resourcepack";Navigate("Mods");await modsLoadTask;return;}if(name=="MotionChecks"&&previewRoot!=null){await CheckMotionAsync(previewRoot);return;}if(name=="CompactPreview"){Width=1080;Height=760;Navigate("Home");return;}if(name=="ModsIcons"&&previewRoot!=null){await CheckModIconsAsync(previewRoot);return;}if(name=="ModsChecks"&&previewRoot!=null){await CheckModsUiAsync(previewRoot);return;}if(name=="ModsPreview"){Navigate("Mods");await modsLoadTask;return;}if(name=="SkinsPreview"&&previewRoot!=null){pendingSkin=File.ReadAllBytes(Path.Combine(previewRoot,"skin-preview.png"));Navigate("Skins");return;}if(name=="UiChecks"&&previewRoot!=null){await CheckUiAsync(previewRoot);return;}if(name=="Download"&&previewRoot!=null){var data=System.Text.Json.JsonSerializer.Deserialize<InstallProgress>(File.ReadAllText(Path.Combine(previewRoot,"download-progress.json")));if(data!=null){DownloadPanel.Visibility=Visibility.Visible;ShowDownloadProgress(data);}return;}if(name is "Picker" or "Catalog"){await LoadCatalogAsync();if(name=="Catalog"){pickerMode="Remote";ApplyPickerFilter();}var content=(FrameworkElement)VersionPopup.Child;content.Measure(new Size(580,520));content.Arrange(new Rect(content.DesiredSize));content.UpdateLayout();}else Navigate(name);}
 public FrameworkElement PreviewSurface(string name)=>name is "Picker" or "Catalog"?(FrameworkElement)VersionPopup.Child:this;
 void Nav_Click(object sender,RoutedEventArgs e)=>Navigate((string)((Button)sender).Tag);
 void VersionCard_Click(object sender,RoutedEventArgs e){if(installing)return;selectedChoice=(VersionEntry)((Button)sender).Tag;settings.Version=selectedChoice.Id;pickerMode="All";UpdateChoices(selectedChoice.Id);Status(Loc.T("Выбрано: ")+selectedChoice.Id);}
 void Version_Changed(object sender,SelectionChangedEventArgs e){if(!initialized||updatingChoices||VersionCombo.SelectedItem is not VersionEntry v)return;selectedChoice=v;settings.Version=v.Id;UpdateLaunchButton();VersionPopup.IsOpen=false;Status(v.Installed?Loc.T($"{v.Id} · {v.Loader} · требуется Java {v.JavaMajor}"):Loc.T($"{v.Id} · доступна загрузка с Mojang"));if(page=="Mods")_ = OpenModsAsync();if(page=="Worlds")ShowFiles();}

 void Search_Changed(object sender,TextChangedEventArgs e){if(AllVersions!=null)AllVersions.ItemsSource=versions.Where(v=>v.Title.Contains(SearchBox.Text,StringComparison.OrdinalIgnoreCase)||v.Loader.Contains(SearchBox.Text,StringComparison.OrdinalIgnoreCase));}
 async void Refresh_Click(object sender,RoutedEventArgs e)=>await RefreshVersions();
 void Ram_Changed(object sender,RoutedPropertyChangedEventArgs<double> e){if(RamLabel!=null)RamLabel.Text=Loc.T($"{e.NewValue/1024:0.#} ГБ");}
 void BrowseRoot_Click(object sender,RoutedEventArgs e){var dialog=new OpenFolderDialog{Title=Loc.T("Папка Minecraft с versions, assets, libraries"),InitialDirectory=Directory.Exists(RootBox.Text)?RootBox.Text:Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData)};if(dialog.ShowDialog()==true)RootBox.Text=dialog.FolderName;}
 void BrowseJava_Click(object sender,RoutedEventArgs e){var dialog=new OpenFileDialog{Title=Loc.T("Java для запуска игры"),Filter="Java (java.exe)|java.exe"};if(dialog.ShowDialog()==true)JavaBox.Text=dialog.FileName;}
 async void SaveSettings_Click(object sender,RoutedEventArgs e){if(installing){Status(Loc.T("Дождись окончания загрузки или отмени её."),true);return;}try{if(string.IsNullOrWhiteSpace(RootBox.Text))throw new InvalidDataException(Loc.T("Укажи папку игры."));SaveUpgradeSettings();settings.GameRoot=Path.GetFullPath(RootBox.Text);Directory.CreateDirectory(settings.GameRoot);settings.JavaPath=JavaBox.Text.Trim();settings.MemoryMb=(int)RamSlider.Value;settings.ReduceMotion=MotionBox.IsChecked==true;ApplyMotionPreference();settings.Isolated=IsolatedBox.IsChecked==true;PersistNickname();settings.Save();await RefreshVersions();Status(Loc.T("Настройки сохранены"));}catch(Exception ex){Status(ex.Message,true);}}
 LauncherSettings Snapshot()=>new(){GameRoot=SelectedChoice?.RootOverride??settings.GameRoot,GameWidth=settings.GameWidth,GameHeight=settings.GameHeight,Fullscreen=settings.Fullscreen,Nickname=NicknameBox.Text.Trim(),Version=settings.Version,JavaPath=settings.JavaPath,MemoryMb=settings.MemoryMb,Isolated=settings.Isolated,ReduceMotion=settings.ReduceMotion,SkinEnabled=settings.SkinEnabled,SkinModel=settings.SkinModel};
 async void Verify_Click(object sender,RoutedEventArgs e){if(SelectedChoice is not VersionEntry v)return;var s=Snapshot();Status(Loc.T("Проверка библиотек, Java и ресурсов…"));try{var result=await Task.Run(()=>{var p=LaunchEngine.Build(s,v.Id);var a=LaunchEngine.CheckAssets(s,p);return(p,a);});Log(result.p.Summary);foreach(string missing in result.p.Missing.Take(40))Log(Loc.T("Нет: ")+missing);Log(Loc.T($"Отсутствующих объектов ресурсов: {result.a.Count}"));foreach(string missing in result.a.Take(12))Log(Loc.T("Ресурс: ")+missing);Status(result.p.Missing.Count+result.a.Count==0?Loc.T("Все необходимые файлы найдены. Офлайн-запуск доступен."):Loc.T("Не хватает файлов. Подробности в журнале."),result.p.Missing.Count+result.a.Count>0);}catch(Exception ex){Log(ex.Message);Status(ex.Message,true);}}
 async void Play_Click(object sender,RoutedEventArgs e){if(game is {HasExited:false}){await StopGameAsync();return;}if(installing||launching||SelectedChoice is not VersionEntry v)return;if(!v.Installed){await InstallChoiceAsync(v);return;}launching=true;if(page=="Skins")RefreshSkin();PlayButton.IsEnabled=false;PlayButton.Content=Loc.T("ПРОВЕРКА…");VersionCombo.IsEnabled=false;RefreshModInstallState();var s=Snapshot();try{Status(Loc.T("Проверка офлайн-профиля и файлов…"));var result=await Task.Run(()=>{var p=LaunchEngine.Build(s,v.Id);var a=LaunchEngine.CheckAssets(s,p);return(p,a);});if(result.p.Missing.Count>0||result.a.Count>0){foreach(string missing in result.p.Missing.Take(40))Log(Loc.T("Нет: ")+missing);Log(Loc.T("Отсутствующих ресурсов: ")+result.a.Count);throw new InvalidOperationException(Loc.T("Не хватает файлов для офлайн-запуска. Открой журнал; сначала установи эту версию полностью."));}
  settings.Nickname=s.Nickname;settings.Save();Directory.CreateDirectory(LauncherSettings.DataRoot);logfile?.Dispose();logfile=new StreamWriter(Path.Combine(LauncherSettings.DataRoot,"latest-launch.log"),false){AutoFlush=true};Log(Loc.T($"Запуск {v.Id} / Java {result.p.Version.JavaMajor} / {s.MemoryMb} МБ / локальный профиль."));Log(Loc.T("Игровая папка: ")+result.p.GameDirectory);if(s.SkinEnabled){if(!result.p.Version.Libraries.Keys.Any(k=>k.StartsWith("com.mojang:authlib",StringComparison.Ordinal)))throw new InvalidOperationException(Loc.T("Локальные скины поддерживаются начиная с Minecraft 1.7.2. Выключи скин для этой старой версии."));Status(Loc.T("Подключение локального скина…"));skinSession=await LocalSkins.PrepareAsync(s,Environment.ProcessPath!);skinSession.Apply(result.p);}game=await Task.Run(()=>LaunchEngine.Start(result.p));skinSession?.Attach(game);game.OutputDataReceived+=(a,b)=>{if(b.Data!=null)Log(b.Data);};game.ErrorDataReceived+=(a,b)=>{if(b.Data!=null)Log(b.Data);};game.BeginOutputReadLine();game.BeginErrorReadLine();PlayButton.Content=Loc.T(Loc.T("ЗАКРЫТЬ ИГРУ  ■"));PlayButton.IsEnabled=true;if(settings.MinimizeOnLaunch)WindowState=WindowState.Minimized;Status(Loc.T("Minecraft запущен. Лаунчер можно закрыть — игра продолжит работать."));await game.WaitForExitAsync();int code=game.ExitCode;Log(Loc.T("Игра завершена. Код: ")+code);Status(code==0?Loc.T("Игра закрыта. До нового приключения!"):Loc.T("Игра завершилась с ошибкой. Подробности в журнале."),code!=0);if(code!=0)Navigate("Logs");game.Dispose();game=null;
 }catch(Exception ex){Log(ex.Message);Status(ex.Message,true);Navigate("Logs");}finally{skinSession?.Dispose();skinSession=null;launching=false;if(page=="Skins")RefreshSkin();VersionCombo.IsEnabled=true;UpdateLaunchButton();RefreshModInstallState();}}
 void ShowFiles(){FileRows.Children.Clear();if(SelectedChoice is not VersionEntry v){FilesDescription.Text=Loc.T("Сначала выбери версию игры.");filesFolder="";return;}string gameDir=LaunchEngine.InstanceDirectory(SettingsFor(v),v.Id);filesFolder=Path.Combine(gameDir,page=="Mods"?(catalogType switch{"resourcepack"=>"resourcepacks","shader"=>"shaderpacks",_=>"mods"}):"saves");FilesDescription.Text=$"{v.Title} · "+(settings.Isolated?Loc.T("Отдельная папка сборки"):Loc.T("Исходная папка Minecraft"));
  var names=Directory.Exists(filesFolder)?(page=="Mods"?Directory.GetFiles(filesFolder,catalogType!="mod"?"*.zip":"*.jar"):Directory.GetDirectories(filesFolder)).OrderBy(Path.GetFileName).ToArray():Array.Empty<string>();if(names.Length==0){FileRows.Children.Add(new TextBlock{Text=page=="Mods"?(catalogType=="shader"?Loc.T("Шейдеров пока нет. Установи ZIP из каталога Modrinth."):catalogType=="resourcepack"?Loc.T("Ресурспаков пока нет. Установи ZIP из каталога Modrinth."):Loc.T("Здесь пока нет модов. Открой папку и добавь совместимые JAR-файлы.")):Loc.T("Миров пока нет. Создай первый мир в игре."),Foreground=Brushes.DarkSeaGreen,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,15,0,0)});return;}
  foreach(string path in names){var row=new Grid();row.ColumnDefinitions.Add(new(){Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new(){Width=GridLength.Auto});row.Children.Add(new TextBlock{Text=Path.GetFileName(path),TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(0,0,15,0)});var button=new Button{Content=Loc.T("Показать ↗"),Tag=path,Padding=new Thickness(12,7,12,7)};button.Click+=(s,e)=>OpenFolder(page=="Mods"?Path.GetDirectoryName((string)button.Tag)!:(string)button.Tag);Grid.SetColumn(button,1);row.Children.Add(button);FileRows.Children.Add(new Border{Background=new SolidColorBrush(Color.FromRgb(26,35,37)),CornerRadius=new CornerRadius(9),Padding=new Thickness(15),Margin=new Thickness(0,0,0,9),Child=row});}}
 void OpenFolder(string path){try{Directory.CreateDirectory(path);var psi=new ProcessStartInfo("explorer.exe"){UseShellExecute=true};psi.ArgumentList.Add(path);Process.Start(psi);}catch(Exception e){Status(e.Message,true);}}
 void FilesFolder_Click(object sender,RoutedEventArgs e){if(filesFolder!="")OpenFolder(filesFolder);}
 void LogFolder_Click(object sender,RoutedEventArgs e)=>OpenFolder(LauncherSettings.DataRoot);
